import torch.nn as nn
from torch.utils.cpp_extension import load_inline
_cpp_src = r"""
#include <torch/extension.h>
torch::Tensor depthwise_conv2d_kx1(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation);
"""
_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <ATen/AccumulateType.h>
#include <c10/cuda/CUDAException.h>
#include <algorithm>
constexpr int TILE_X = 32;
constexpr int TILE_Y = 8;
constexpr int RB_Y = 4;
constexpr int OUT_TILE_Y = TILE_Y * RB_Y;
template <typename scalar_t>
__global__ void depthwise_conv2d_kx1_kernel(
    const scalar_t* __restrict__ x,
    const scalar_t* __restrict__ w,
    const scalar_t* __restrict__ b,
    scalar_t* __restrict__ out,
    int64_t C,
    int64_t H,
    int64_t W,
    int64_t K,
    int64_t OH,
    int64_t OW,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    bool has_bias,
    int64_t tiles_x) {
    extern __shared__ __align__(16) unsigned char smem_raw[];
    scalar_t* smem = reinterpret_cast<scalar_t*>(smem_raw);
    const int64_t tile_lin = blockIdx.x;
    const int64_t tile_x = tile_lin % tiles_x;
    const int64_t tile_y = tile_lin / tiles_x;
    const int64_t nc = blockIdx.y;
    const int64_t c = nc % C;
    const int64_t tx0 = tile_x * TILE_X;
    const int64_t ty0 = tile_y * OUT_TILE_Y;
    const int64_t xo = tx0 + threadIdx.x;
    const int64_t y_base = ty0 + threadIdx.y * RB_Y;
    const int64_t SW = (TILE_X - 1) * stride + 1;
    const int64_t SH = (OUT_TILE_Y - 1) * stride + (K - 1) * dilation + 1;
    const int64_t r0 = ty0 * stride - padding;
    const int64_t c0 = tx0 * stride - padding;
    const int64_t base = nc * H * W;
    for (int64_t t = threadIdx.y * TILE_X + threadIdx.x; t < SH * SW; t += TILE_X * TILE_Y) {
        const int64_t rr = t / SW;
        const int64_t cc = t - rr * SW;
        const int64_t gr = r0 + rr;
        const int64_t gc = c0 + cc;
        scalar_t v = static_cast<scalar_t>(0);
        if (gr >= 0 && gr < H && gc >= 0 && gc < W) {
            v = x[base + gr * W + gc];
        }
        smem[t] = v;
    }
    __syncthreads();
    if (xo < OW) {
        using acc_t = at::acc_type<scalar_t, true>;
        const acc_t bias_acc = has_bias ? static_cast<acc_t>(b[c]) : static_cast<acc_t>(0);
        const int64_t lc = threadIdx.x * stride;
        const int64_t w_base = c * K;
        #pragma unroll
        for (int r = 0; r < RB_Y; ++r) {
            const int64_t yo = y_base + r;
            if (yo < OH) {
                acc_t acc = bias_acc;
                const int64_t lr = (threadIdx.y * RB_Y + r) * stride;
                for (int64_t k = 0; k < K; ++k) {
                    acc += static_cast<acc_t>(smem[(lr + k * dilation) * SW + lc]) * static_cast<acc_t>(w[w_base + k]);
                }
                out[(nc * OH + yo) * OW + xo] = static_cast<scalar_t>(acc);
            }
        }
    }
}
torch::Tensor depthwise_conv2d_kx1(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation) {
    TORCH_CHECK(x.is_cuda());
    TORCH_CHECK(weight.is_cuda());
    TORCH_CHECK(x.dim() == 4);
    TORCH_CHECK(weight.dim() == 4);
    TORCH_CHECK(weight.size(1) == 1);
    TORCH_CHECK(weight.size(3) == 1);
    TORCH_CHECK(weight.size(0) == x.size(1));
    TORCH_CHECK(stride >= 1 && dilation >= 1);
    auto xc = x.contiguous();
    auto wc = weight.contiguous();
    const bool has_bias = bias.has_value() && bias.value().defined();
    torch::Tensor bc;
    if (has_bias) {
        TORCH_CHECK(bias.value().is_cuda());
        TORCH_CHECK(bias.value().numel() == x.size(1));
        bc = bias.value().contiguous();
    }
    const int64_t N = xc.size(0);
    const int64_t C = xc.size(1);
    const int64_t H = xc.size(2);
    const int64_t W = xc.size(3);
    const int64_t K = wc.size(2);
    const int64_t OH = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int64_t OW = (W + 2 * padding - 1) / stride + 1;
    TORCH_CHECK(OH >= 0 && OW >= 0);
    auto out = torch::empty({N, C, OH, OW}, xc.options());
    const int64_t total = N * C * OH * OW;
    if (total == 0) {
        return out;
    }
    const int64_t tiles_x = (OW + TILE_X - 1) / TILE_X;
    const int64_t tiles_y = (OH + OUT_TILE_Y - 1) / OUT_TILE_Y;
    const int64_t grid_x = tiles_x * tiles_y;
    const int64_t grid_y = N * C;
    TORCH_CHECK(grid_x <= 2147483647LL && grid_y <= 65535LL);
    const int64_t SW = (TILE_X - 1) * stride + 1;
    const int64_t SH = (OUT_TILE_Y - 1) * stride + (K - 1) * dilation + 1;
    const int64_t smem_bytes64 = SH * SW * c10::elementSize(xc.scalar_type());
    TORCH_CHECK(smem_bytes64 <= 48 * 1024);
    const int smem_bytes = static_cast<int>(smem_bytes64);
    dim3 block(TILE_X, TILE_Y);
    dim3 grid(static_cast<unsigned int>(grid_x), static_cast<unsigned int>(grid_y));
    AT_DISPATCH_FLOATING_TYPES_AND_HALF(xc.scalar_type(), "depthwise_conv2d_kx1_cuda", [&] {
