        self.conv2d = nn.Conv2d(
            in_channels,
            in_channels,
            kernel_size=(kernel_size, 1),
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=in_channels,
            bias=bias,
        )
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _mod.depthwise_conv2d_kx1(
            x,
            self.conv2d.weight,
            self.conv2d.bias,
            self.conv2d.stride[0],
            self.conv2d.padding[0],
