#include <ATen/cuda/CUDAContext.h>
#include <ATen/AccumulateType.h>
#include <c10/cuda/CUDAException.h>
#include <algorithm>

template <typename scalar_t>
__global__ void depthwise_conv2d_kx1_kernel(
    const scalar_t* __restrict__ x,
    const scalar_t* __restrict__ w,
    const scalar_t* __restrict__ b,
    scalar_t* __restrict__ out,
    int64_t N,
    int64_t C,
    int64_t H,
    int64_t W,
    int64_t K,
    int64_t OH,
    int64_t OW,
    int64_t stride,
    int64_t padding,
    int64_t dilation,
    bool has_bias,
    int64_t total) {
    const int64_t step = (int64_t)gridDim.x * blockDim.x;
    for (int64_t idx = (int64_t)blockIdx.x * blockDim.x + threadIdx.x; idx < total; idx += step) {
        int64_t t = idx;
        const int64_t xo = t % OW;
        t /= OW;
        const int64_t yo = t % OH;
        t /= OH;
        const int64_t c = t % C;
        const int64_t n = t / C;

        using acc_t = at::acc_type<scalar_t, true>;
        acc_t acc = has_bias ? static_cast<acc_t>(b[c]) : static_cast<acc_t>(0);

        const int64_t wi = xo * stride - padding;
        const bool w_ok = (wi >= 0 && wi < W);
        for (int64_t k = 0; k < K; ++k) {
            const int64_t hi = yo * stride - padding + k * dilation;
            if (w_ok && hi >= 0 && hi < H) {
                const int64_t x_idx = ((n * C + c) * H + hi) * W + wi;
                acc += static_cast<acc_t>(x[x_idx]) * static_cast<acc_t>(w[c * K + k]);
            }
        }
        out[idx] = static_cast<scalar_t>(acc);
    }
}

torch::Tensor depthwise_conv2d_kx1(
    torch::Tensor x,
    torch::Tensor weight,
    c10::optional<torch::Tensor> bias,
    int64_t stride,
    int64_t padding,
    int64_t dilation) {
    TORCH_CHECK(x.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 4, "input must be NCHW");
    TORCH_CHECK(weight.dim() == 4, "weight must be (C, 1, K, 1)");
    TORCH_CHECK(weight.size(1) == 1, "depthwise Kx1 weight must have size(1) == 1");
    TORCH_CHECK(weight.size(3) == 1, "only Kx1 kernels are supported");
    TORCH_CHECK(weight.size(0) == x.size(1), "depthwise weight channels must match input channels");
    TORCH_CHECK(stride >= 1 && dilation >= 1, "invalid stride/dilation");

    auto xc = x.contiguous();
    auto wc = weight.contiguous();
    const bool has_bias = bias.has_value() && bias.value().defined();
    torch::Tensor bc;
    if (has_bias) {
        TORCH_CHECK(bias.value().is_cuda(), "bias must be a CUDA tensor");
        TORCH_CHECK(bias.value().numel() == x.size(1), "bias must have one element per channel");
        bc = bias.value().contiguous();
    }

    const int64_t N = xc.size(0);
    const int64_t C = xc.size(1);
    const int64_t H = xc.size(2);
    const int64_t W = xc.size(3);
    const int64_t K = wc.size(2);

    const int64_t OH = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
    const int64_t OW = (W + 2 * padding - 1) / stride + 1;
    TORCH_CHECK(OH >= 0 && OW >= 0, "invalid output shape");

    auto out = torch::empty({N, C, OH, OW}, xc.options());
    const int64_t total = N * C * OH * OW;
    if (total == 0) {
        return out;
    }

    const int64_t block = 256;
    const int64_t grid64 = std::min<int64_t>((total + block - 1) / block, 2147483647LL);
    const unsigned int grid = static_cast<unsigned int>(grid64);

    AT_DISPATCH_FLOATING_TYPES_AND_HALF(xc.scalar_type(), "depthwise_conv2d_kx1_cuda", [&] {
        const scalar_t* bptr = has_bias ? bc.data_ptr<scalar_t>() : nullptr;
        depthwise_conv2d_kx1_kernel<scalar_t><<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
            xc.data_ptr<scalar_t>(),
            wc.data_ptr<scalar_t>(),
            bptr,
            out.data_ptr<scalar_t>(),
            N, C, H, W, K, OH, OW,
            stride, padding, dilation,
            has_bias,
            total);
    });
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
"""

_mod = load_inline(
    name="depthwise_conv2d_kx1_ext",
    cpp_sources=[_cpp_src],
    cuda_sources=[_cuda_src],
    functions=["depthwise_conv2d_kx1"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, dilation: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv2d = nn.Conv2d(
            in_channels,
            in_channels,
            kernel_size=(kernel_size, 1),
            stride=stride,
            padding=padding,
            dilation=dilation,
            groups=in_channels,
            bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _mod.depthwise_conv2d_kx1(
            x,
            self.conv2d.weight,
            self.conv2d.bias,
            self.conv2d.stride[0],
            self.conv2d.padding[0],
            self.conv2d.dilation[0],
        )
